import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 32

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    int bx = blockIdx.x; // tile index along columns
    int by = blockIdx.y; // tile index along rows

    // Entire block lies strictly below the diagonal -> result is all zeros
    if (by > bx) return;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE + ty;
    int col = bx * TILE + tx;

    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    float sum = 0.0f;

    // Only need to accumulate over k tiles from 'by' to 'bx' because
    // A is upper triangular (A[i][k] = 0 for k < i) and
    // B is upper triangular (B[k][j] = 0 for k > j).
    for (int kb = by; kb <= bx; ++kb) {
        int aCol = kb * TILE + tx;
        int aRow = row;
        As[ty][tx] = (aRow < N && aCol < N) ? A[aRow * N + aCol] : 0.0f;

        int bRow = kb * TILE + ty;
        int bCol = col;
        Bs[ty][tx] = (bRow < N && bCol < N) ? B[bRow * N + bCol] : 0.0f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        if (row <= col) {
            C[row * N + col] = sum;
        } else {
            C[row * N + col] = 0.0f;
        }
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);

    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

triu_matmul_cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul = load_inline(
    name="triu_matmul",
    cpp_sources=triu_matmul_cpp_source,
    cuda_sources=triu_matmul_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom fused CUDA kernel that exploits the
    triangular structure of A and B to reduce redundant computation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.triu_matmul = triu_matmul

    def forward(self, A, B):
        return self.triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N)).cuda()
    B = torch.triu(torch.rand(N, N)).cuda()
    return [A, B]

def get_init_inputs():
    return []

